  + duration : int
  + publisher : string
}

class Actor {
  + name : string
}

class Request {
}

class ItemRequest {
}

class Borrowing {
  + due_date : date
}

class BookAuthor {
  + name : string
}

Book extends BorrowableItem
MagazineIssue extends BorrowableItem
MusicCD extends BorrowableItem
Film extends BorrowableItem

class DVDFilm extends Film {}

Library "1" -- "*" User : has
Library "1" -- "*" BorrowableItem : has
Library "1" -- "*" Request : receives

User "1" -- "*" Borrowing : makes
Borrowing "1" -- "1" BorrowableItem : involves

User "0..1" -- "0..1" BorrowableItem : borrows

User "1" -- "*" Request : sends
Request "1" -- "1" ItemRequest : contains
ItemRequest "*" -- "1" BorrowableItem : for

Book "1" -- "1..*" BookAuthor : written by
Film "1" -- "1..*" Actor : features

@enduml

